Lemma wslots_out : forall vs m a (x : word),
  0 <= a -> a + 8 * Z.of_nat (length vs) <= 2 ^ 64 ->
  (bv_unsigned x < a \/ a + 8 * Z.of_nat (length vs) <= bv_unsigned x) -> wslots m a vs x = m x.
