Lemma wslots_slot : forall vs m a i,
  0 <= a -> a + 8 * Z.of_nat (length vs) <= 2 ^ 64 -> (i < length vs)%nat ->
  rdn segs (wslots m a vs) (Z_to_bv 64 (a + 8 * Z.of_nat i)) 8%nat = Some (word_to_le_bytes 8 (nth i vs (Z_to_bv 64 0))).
