Lemma step_diamond_sound : forall (fx : FPState) jp ss w ss' w' E R M,
  closed ss w = true -> step_diamond jp ss w = Some (ss', w') -> INV E ss w R M ->
  STEP_POST fx ss w ss' w' E R M (seg_rom segs).
Proof.
