Lemma region_flat_chk_sound : forall E M kn r,
  know_ok segs E M kn -> region_flat_chk kn r = true ->
  let '(rb, rlo, rlen) := r in 0 <= estart E (SA rb rlo) /\ 0 < rlen < 2 ^ 64 /\ estart E (SA rb rlo) + rlen <= 2 ^ 64.
Proof.
